import 'dart:convert';
import 'dart:typed_data';

const Map<String, String> kFixtureBase64 = <String, String>{
  'heic/gradient_640x480.heic': '',
  'heic/portrait_orientation6.heic': '',
  'heic/with_gps.heic': '',
  'jpeg/with_gps.jpg': '',
  'png/gradient_320x240.png': '',
};

Uint8List fixtureBytes(String relative) {
  final encoded = kFixtureBase64[relative];
  if (encoded == null) {
    throw ArgumentError.value(
      relative,
      'relative',
      'unknown fixture; known: ${kFixtureBase64.keys.join(', ')}',
    );
  }
  return base64Decode(encoded);
}
